KW=re.compile(r'(?i)\b(dj|vdj|dvj|deejay|remix|mix|edit|style|suited|blend|bootleg|dhol|clap|drop|troll|psy|festive|original|version|tapori|retro|modern|dialogue|hip hop|jungle|punjabi|bollywood|desi|live|bpm|extended|club|prod|reloaded|official|lyrical|video|audio|kannada|tamil|telugu|telgu|female|male|dance|from|reprise|mashup|bass|funk|vibe|anthem|kingz|dual lingo|urdu|bengali|gujarati|kashmiri|multi track|title track|ost)\b|\d+m\b|\d{2,3}\b')
PRODUCERS=re.compile(r'(?i)^(ravish|chico|tejas|abhijit|akhil|shameless|skeletron|samz|third dimension|harsh bhutani|lemon|oppozit|yoschi|kawal|mintz|manan|trux|sartek|kshmr|allinmohi|aidd|starjack|mister gray|mattlok|sarfraz|sarfaraz|any ?me.*|afterjoy|anirudha.*|j&u.*|mr jammer|dhyan|muzik mafia|ansick|clement|honey|hpo|sclef|kudos.*|karanedits|raul music|ajay solanki|dylan|urban singh|mag x|panic x arah.*|druminem|reonn.*|flipsyd|ahmed spins.*|vicetone|fytr|keep me.*|avin|soundrex.*|ribin richard|kratex.*|spade|tote|bekay|chiney|giacobbi|tucci|mamba|yjay|mauricio|petedown|xxl|2ks|r3hab|hardwell|zedd|ziggy.*|joe maz.*|massive rock.*|fat tony|walker & daniels|robin roij|dvjfabietto|anthem kingz|shanaya|djmrc|mikis|dberrie|mhark|giacobbi|jim craane|frankie steel|phase|sandersville.*|cody dunstall.*|steve d|minost.*|stavros.*|samuel pedrozo|joan qveralt|young fresh|art brothers|shahin.*|dbmafia.*|dutch sauce.*|tom barker|kuduro|blucks|wescalatie|max me.*|the goodfellas|thomas rush.*|bertra.*|scooter|seb barra.*|donofrio|nath je.*|fissa united|wado.*|pqz|joe reece|bomb a drop|mr\.? m!x|glenn-d|loud raverz.*|fuseaman|radioclouds|noiseyboiz|onur|slick|ortega|diamatik|holsh|hope|cloud.*|asil|juize|ragoza|spice|denis?.*|crizac|sj|kraken.*|saydun.*|golden|power|fiyan|allan|jeff|deo|mark shark|.*\bx\b.*\bdj\b.*|trugg|neel|rjb|hans|tushar|lioyd|kahaan uk|veronika|faith|kavish|sue project.*|sukhi.*|montz|ruhi|dalal london|ground|block beatz|rink|ajay|ajmal|groovedev|syrah.*|khyati.*|deep nyc|mayank|ashmac|purvish|raney|abhijeet|rhea|goddess|rytech.*|rushi.*|myra.*|vaibha.*|doc|smita|rv|fire|snky|ritika|chetas|nihar|franky|resque|toons|sizzle|shizzle|perspekt.*|vanohn|ad|subham maity|nrs|redz mumbai|alex ngp|gaurav.*|nandish.*|sagar kadam|utkarsh|san j|vaggy.*|honey|sid|adio.*|baichun|baichu|kedrol.*|sunny groove|nexus|pami|deepsi|piyush bajaj|kaash|amit saxena|sitans|irfan.*|vihaan|ay|lijo|parth|chetas|anik|dharak|aaditya|raizestrom|manix|toxic.*|lucky.*|sheryl|dhaval|ankit rohida.*|partha.*|donnaa|honey|somairah|kidz|rony india|sajan|pooja|ssunny|abhishek|ash|shadow dubai|danny|ramesh ex.*|shri|shad india|prem mittal|swana|snaky|kamya|harish|jazzy.*|yogii|anant|nilashree.*|shreya.*|srv.*|vfrecue|sumit|biplab.*|scorpio.*|pratikk|lloyd|pin2|reme|samz|sam|kayu|onur|ronn|ankish|vvaan|hitz|mani|abhi.*|sukhi dubai.*|aayush|dub yash|asim|dits|kamra.*|neo|karan|param.*|myk.k|ee.*|nasa|raj roy|happy chopra|happy|vijay khathuria|harshit shah|vijaypath|sanket koli|shubham k.*|dhruv|tom brandon|abdul.*|ayush j.*|raag sing.*|sujal|vijay|sagar|pr & .*|ravi|strawz|mayur.*|chico.*|telgu tapori.*)$')
def disp(title,eng=False):
    t=title.replace('꞉',':').strip()
    if eng:
        t=re.sub(r'\s*[\(\[].*?[\)\]]','',t)
    else:
        def rep(m):
            inner=m.group(1)
            if KW.search(inner) or PRODUCERS.match(inner.strip()): return ''
            return m.group(0)
        for _ in range(2): t=re.sub(r'\s*[\(\[]([^\(\)\[\]]*)[\)\]]',rep,t)
    t=re.sub(r'\s*[\(\[][^\)\]]*$','',t)  # unterminated
    t=re.sub(r'\s+',' ',t).strip(' -·')
    return t
